-- Stock Action by OTD | proposed PostgreSQL migration 0001
-- Architecture scaffold only; NOT applied to any database.
-- Review with DBA/security engineer before deploying.
create extension if not exists pgcrypto;
create table tenants(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table tenant_memberships(tenant_id uuid not null references tenants(id),user_id uuid not null,role text not null check(role in ('owner','admin','cashier','stock_clerk','viewer')),primary key(tenant_id,user_id));
create table stores(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,unique(tenant_id,id));
create table products(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),name text not null,category text not null,created_at timestamptz not null default now(),unique(tenant_id,id));
create table variants(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),product_id uuid not null,sku text not null,size text,color text,price_paise bigint not null check(price_paise>=0),cost_paise bigint not null check(cost_paise>=0),unique(tenant_id,sku),unique(tenant_id,id),foreign key(tenant_id,product_id) references products(tenant_id,id));
create table locations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),store_id uuid not null,label text not null,kind text not null check(kind in ('sellable','damaged','in_transit','quarantine')),unique(tenant_id,id),foreign key(tenant_id,store_id) references stores(tenant_id,id));
create table stock_balances(tenant_id uuid not null,variant_id uuid not null,location_id uuid not null,on_hand bigint not null default 0 check(on_hand>=0),reserved bigint not null default 0 check(reserved>=0 and reserved<=on_hand),version bigint not null default 0,primary key(tenant_id,variant_id,location_id),foreign key(tenant_id,variant_id) references variants(tenant_id,id),foreign key(tenant_id,location_id) references locations(tenant_id,id));
create table stock_movements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,variant_id uuid not null,location_id uuid not null,kind text not null check(kind in ('opening','receipt','sale','return','adjustment','transfer_in','transfer_out')),delta bigint not null check(delta<>0),reference_type text not null,reference_id text not null,actor_id uuid,created_at timestamptz not null default now(),foreign key(tenant_id,variant_id,location_id) references stock_balances(tenant_id,variant_id,location_id),unique(tenant_id,reference_type,reference_id,variant_id,location_id,kind));
create table channel_listings(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,variant_id uuid not null,channel text not null,published boolean not null default false,buffer_units bigint not null default 0 check(buffer_units>=0),unique(tenant_id,variant_id,channel),foreign key(tenant_id,variant_id) references variants(tenant_id,id));
create table orders(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),store_id uuid,channel text not null check(channel in ('pos','website','marketplace')),status text not null check(status in ('pending','reserved','paid','fulfilled','cancelled','refund_required')),external_reference text,created_at timestamptz not null default now(),unique(tenant_id,id),unique(tenant_id,channel,external_reference),foreign key(tenant_id,store_id) references stores(tenant_id,id));
create table order_lines(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,order_id uuid not null,variant_id uuid not null,quantity bigint not null check(quantity>0),unit_price_paise bigint not null check(unit_price_paise>=0),foreign key(tenant_id,order_id) references orders(tenant_id,id),foreign key(tenant_id,variant_id) references variants(tenant_id,id));
create table reservations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,order_id uuid not null,variant_id uuid not null,location_id uuid not null,quantity bigint not null check(quantity>0),expires_at timestamptz not null,status text not null check(status in ('held','released','committed')),foreign key(tenant_id,order_id) references orders(tenant_id,id),foreign key(tenant_id,variant_id,location_id) references stock_balances(tenant_id,variant_id,location_id));
create table idempotency_keys(tenant_id uuid not null references tenants(id),operation text not null,key text not null,request_hash text not null,response_body jsonb,created_at timestamptz not null default now(),primary key(tenant_id,operation,key));
create table count_sessions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),location_id uuid not null,status text not null check(status in ('open','submitted','approved','posted','rejected')),opened_at timestamptz not null default now(),approved_by uuid,foreign key(tenant_id,location_id) references locations(tenant_id,id),unique(tenant_id,id));
create table count_lines(tenant_id uuid not null,session_id uuid not null,variant_id uuid not null,snapshot_on_hand bigint not null,physical bigint not null check(physical>=0),primary key(tenant_id,session_id,variant_id),foreign key(tenant_id,session_id) references count_sessions(tenant_id,id),foreign key(tenant_id,variant_id) references variants(tenant_id,id));
create table audit_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references tenants(id),actor_id uuid,action text not null,entity_type text not null,entity_id text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index stock_movements_tenant_created_idx on stock_movements(tenant_id,created_at desc);
create index orders_tenant_created_idx on orders(tenant_id,created_at desc);
create index reservations_expiry_idx on reservations(expires_at) where status='held';
-- RLS should be enabled on ALL tenant tables and correct JWT session scoping policy
-- MUST be implemented and tested BEFORE any client data is allowed.
-- No authenticated client may directly insert into stock_movements or update stock_balances.
-- All mutations must run under transaction-controlled, role-checked server functions.
